1219	\begin{equation*}
1220	\ket{\psi} = \ket{\mathrm{EPR}_{q_1}} \otimes \ket{\mathrm{EPR}_{q_2}} \otimes \cdots \otimes \ket{\mathrm{EPR}_{q_k}}.

